  function_name = "example_function"
  role          = aws_iam_role.lambda_exec.arn
  handler       = "lambda_function.handler"
  runtime       = "python3.8"

  environment {
    variables = {
      key1 = "value1"
      key2 = "value2"
    }
  }
}
```

